import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158561894555',ROOT='body-armor-ballistic-protection';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await chromium.launch({headless:true});
const context=await browser.newContext({viewport:{width:1440,height:1000}});
const normalize=s=>String(s||'').replace(/\s+/g,' ').trim();
async function open(){const p=await context.newPage();await p.goto(`${BASE}/collections/${ROOT}?preview_theme_id=${THEME}`,{waitUntil:'domcontentloaded',timeout:90000});await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:60000});await p.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible'});await sleep(800);return p}
async function inspectChoice(groupTitle,label){const p=await open();const before=await p.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-results .product-grid a[href*="/products/"]')].slice(0,10).map(a=>a.href));const details=p.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').filter({has:p.locator('summary',{hasText:groupTitle})}).first();await details.evaluate(el=>el.open=true);const choice=details.locator('.sq-refine-v3-choice').filter({hasText:label}).first();if(!await choice.count()){await p.close();return{groupTitle,label,missing:true}}const input=choice.locator('input').first();const attrs=await input.evaluate(i=>({type:i.type,name:i.name,value:i.value,kind:i.dataset.kind||'',target:i.dataset.target||'',filterName:i.dataset.filterName||'',filterValue:i.dataset.filterValue||''}));const oldUrl=p.url();await input.check({force:true}).catch(async()=>input.click({force:true}));await Promise.race([p.waitForLoadState('domcontentloaded',{timeout:15000}).catch(()=>{}),sleep(2200)]);await sleep(1800);if((await p.locator('#MainContent .sq-refine-v3-sidebar').count())&&!(await p.locator('#MainContent .sq-refine-v3-sidebar').isVisible().catch(()=>false)))await sleep(1200);const result=await p.evaluate(()=>{const grid=document.querySelector('#MainContent .sq-refine-v3-results .product-grid');const cards=grid?[...grid.querySelectorAll(':scope>.product-grid__item')].filter(x=>x.querySelector('a[href*="/products/"]')):[];return{ready:document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',error:document.querySelector('#MainContent')?.dataset.sqRefineV3Error||'',cards:cards.length,products:cards.slice(0,6).map(x=>(x.textContent||'').replace(/\s+/g,' ').trim().slice(0,180))}});const after=await p.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-results .product-grid a[href*="/products/"]')].slice(0,10).map(a=>a.href));const out={groupTitle,label,attrs,oldUrl,afterUrl:p.url(),changed:oldUrl!==p.url()||JSON.stringify(before)!==JSON.stringify(after),...result};await p.close();return out}
const root=await open();const inventory=await root.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group')].filter(d=>/Shop by (Subcategory|Type)/i.test((d.querySelector('summary')?.textContent||'').trim())).map(d=>({title:(d.querySelector('summary')?.textContent||'').trim(),labels:[...d.querySelectorAll('.sq-refine-v3-choice span')].map(s=>(s.textContent||'').trim())})));await root.close();
console.log('BODY_ARMOR_FILTER_INVENTORY '+JSON.stringify(inventory));
const checks=[];for(const g of inventory){for(const label of g.labels){checks.push(await inspectChoice(g.title,label));}}
console.log('BODY_ARMOR_FILTER_CHECKS '+JSON.stringify(checks));
const failures=[];for(const c of checks){if(c.missing)failures.push(`${c.groupTitle}: ${c.label}: missing`);else if(!c.changed)failures.push(`${c.groupTitle}: ${c.label}: no URL/product change`);else if(!c.ready||c.error||c.cards<1)failures.push(`${c.groupTitle}: ${c.label}: ready=${c.ready} error=${c.error} cards=${c.cards}`)}
console.log('BODY_ARMOR_FILTER_SUMMARY '+JSON.stringify({checked:checks.length,failures}));
await browser.close();if(failures.length)process.exit(1);
